<script setup lang="ts">
import {ref} from 'vue'
import {request,type LoginResult} from '../../shared/api'
const token=ref(''),email=ref(''),password=ref(''),name=ref(''),org=ref(''),selected=ref(''),campaign=ref(''),objective=ref('awareness'),budget=ref(0),error=ref('')
const orgs=ref<Array<{id:string;name:string}>>([]),advertisers=ref<Array<{id:string;name:string;status:string}>>([]),campaigns=ref<Array<{id:string;name:string;status:string;daily_budget_minor:number}>>([])
async function run(fn:()=>Promise<void>){error.value='';try{await fn()}catch(e){error.value=(e as Error).message}}
async function login(){await run(async()=>{token.value=(await request<LoginResult>('/api/v1/auth/login',null,'POST',{email:email.value,password:password.value})).access_token;password.value='';orgs.value=(await request<{organizations:typeof orgs.value}>('/api/v1/partner/organizations',token.value)).organizations;await refresh()})}
async function refresh(){advertisers.value=(await request<{advertisers:typeof advertisers.value}>('/api/v1/ads/advertisers',token.value)).advertisers;campaigns.value=(await request<{campaigns:typeof campaigns.value}>('/api/v1/ads/campaigns',token.value)).campaigns}
async function addAdvertiser(){await run(async()=>{await request('/api/v1/ads/advertisers',token.value,'POST',{organization_id:org.value,name:name.value});name.value='';await refresh()})}
async function addCampaign(){await run(async()=>{await request('/api/v1/ads/campaigns',token.value,'POST',{advertiser_id:selected.value,name:campaign.value,objective:objective.value,daily_budget_minor:budget.value,currency:'KRW'});campaign.value='';await refresh()})}
</script><template><main><h1>Advertiser Center</h1><p>광고주 계정과 캠페인 초안 — 입찰·광고 게재·결제·정산은 아직 미구현</p><p role="alert" class="error" v-if="error">{{error}}</p><form v-if="!token" @submit.prevent="login"><input v-model="email" type="email" placeholder="이메일" required/><input v-model="password" type="password" placeholder="비밀번호" required/><button>로그인</button></form><template v-else><section><h2>광고주 생성</h2><form @submit.prevent="addAdvertiser"><select v-model="org" required><option value="" disabled>기업 조직 선택</option><option v-for="o in orgs" :key="o.id" :value="o.id">{{o.name}}</option></select><input v-model="name" placeholder="광고주 이름" required minlength="2"/><button>광고주 생성</button></form></section><section><h2>캠페인 초안</h2><form @submit.prevent="addCampaign"><select v-model="selected" required><option value="" disabled>광고주 선택</option><option v-for="a in advertisers" :key="a.id" :value="a.id">{{a.name}} ({{a.status}})</option></select><input v-model="campaign" placeholder="캠페인 이름" minlength="2" required/><input v-model="objective" placeholder="목표" minlength="2" required/><input v-model.number="budget" type="number" min="0"/><button>초안 생성</button></form></section><section><h2>내 캠페인</h2><p v-for="c in campaigns" :key="c.id">{{c.name}} · {{c.status}} · {{c.daily_budget_minor}} KRW/일</p></section></template></main></template>
<style>body{font:16px system-ui;background:#f4f6fa;color:#172536}main{max-width:850px;margin:35px auto;background:white;padding:30px;border-radius:12px}section{border:1px solid #ddd;padding:20px;border-radius:10px;margin:16px 0}input,button,select{padding:11px;border:1px solid #ccc;border-radius:8px;margin:5px}button{background:#145bc0;color:white;cursor:pointer}.error{color:#a22}</style>
